-- Function: public.fn_get_user_auth_claims
-- Backup generated on 2026-10-25 20:33:44

CREATE OR REPLACE FUNCTION public.fn_get_user_auth_claims(p_user_id uuid, p_active_org_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(claim_type character varying, claim_value character varying)  LANGUAGE plpgsql AS $function$ BEGIN     -- Roles     RETURN QUERY     SELECT 'role'::VARCHAR, r.name::VARCHAR     FROM user_roles ur      JOIN roles r ON ur.role_id = r.id      WHERE ur.user_id = p_user_id     UNION     SELECT 'role'::VARCHAR, r.name::VARCHAR     FROM user_organization_roles uor      JOIN roles r ON uor.role_id = r.id      JOIN organization_memberships om ON om.user_id = uor.user_id AND om.organization_id = uor.organization_id AND om.status = 'Active'     WHERE uor.user_id = p_user_id AND (uor.organization_id = p_active_org_id OR p_active_org_id IS NULL)     UNION     SELECT 'role'::VARCHAR, 'DaycareTeacher'::VARCHAR     FROM teachers t     WHERE t.user_id = p_user_id AND t.status != 'Inactive';      -- Permissions     RETURN QUERY     SELECT 'permission'::VARCHAR, p.name::VARCHAR     FROM user_roles ur      JOIN role_permissions rp ON ur.role_id = rp.role_id      JOIN permissions p ON rp.permission_id = p.id      WHERE ur.user_id = p_user_id     UNION     SELECT 'permission'::VARCHAR, p.name::VARCHAR     FROM user_organization_roles uor      JOIN organization_memberships om ON om.user_id = uor.user_id AND om.organization_id = uor.organization_id AND om.status = 'Active'     JOIN role_permissions rp ON uor.role_id = rp.role_id      JOIN permissions p ON rp.permission_id = p.id      WHERE uor.user_id = p_user_id AND (uor.organization_id = p_active_org_id OR p_active_org_id IS NULL)     UNION     SELECT 'permission'::VARCHAR, p.name::VARCHAR     FROM teachers t     JOIN roles r ON r.name IN ('DaycareTeacher', 'ClassroomTeacher', 'Teacher')     JOIN role_permissions rp ON r.id = rp.role_id     JOIN permissions p ON rp.permission_id = p.id     WHERE t.user_id = p_user_id AND t.status != 'Inactive'; END; $function$ ;
